SELECT 'VERSION_PCGE', id, id, 'IMPORTACION', 'Carga inicial del catálogo oficial PCGE Modificado 2019',
       '{"elementos":10,"cuentas":1772,"porDigitos":{"2":82,"3":322,"4":645,"5":702,"6":21},"sha256":"f3c683d973a834fcb26e3283f062350ec8df9d89102b2443467b2a9fee7b2e7c","erratasDocumentadas":12}'::jsonb,
       'sistema'
FROM version_pcge WHERE codigo = 'PCGE_2019';

DO $$
DECLARE
    n_cuentas   INTEGER;
    n_elementos INTEGER;
    n_huerfanas INTEGER;
BEGIN
    SELECT count(*) INTO n_cuentas FROM cuenta_contable c JOIN version_pcge v ON v.id = c.version_id WHERE v.codigo = 'PCGE_2019';
    SELECT count(*) INTO n_elementos FROM elemento_contable e JOIN version_pcge v ON v.id = e.version_id WHERE v.codigo = 'PCGE_2019';
    SELECT count(*) INTO n_huerfanas FROM cuenta_contable c JOIN version_pcge v ON v.id = c.version_id
     WHERE v.codigo = 'PCGE_2019' AND c.nivel > 2 AND c.padre_id IS NULL;
    IF n_cuentas <> 1772 OR n_elementos <> 10 OR n_huerfanas <> 0 THEN
        RAISE EXCEPTION 'Verificación fallida en PCGE_2019: % cuentas, % elementos, % huérfanas', n_cuentas, n_elementos, n_huerfanas;
    END IF;
END $$;
